/** 
 * Helper method to write a line to a File. Extracted to a separate method here to make it a little easier to replace implementations.
 * @param line   The line to write
 * @param writer The place to write it
 * @throws IOException if an I/O error occurs
 */
private static void write(String line, OutputStreamWriter writer) throws IOException {
  synchronized (writer) {
    writer.write(line);
  }
}
